/*
 * A178528  Tree generated by the Beatty sequence of sqrt(3).
 * https://oeis.org/A178528
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(1)=1, a(2)=2; for n≥3 let x be the (n‑1)th value, then a(n) =
 *            floor(√3·x) if n is odd, = floor(s·x) if n is even, where s =
 *            (3+√3)/2. This is equivalent to a breadth‑first traversal of the
 *            tree with root 1, child of 1 = 2, and for any node v≥2:
 *            child0(v) = floor(√3·v) = floor_sqrt(3*v*v) child1...
 * Range:     u8 n <= 4, u16 n <= 47, u32 n <= 2936, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/floor_sqrt.h"

/* cache for already generated terms */
static seq_t *cache = NULL;
static size_t   cache_len = 0;
static size_t   cache_cap = 0;

/* queue for breadth‑first traversal */
static seq_t *queue = NULL;
static size_t  q_head = 0;
static size_t  q_tail = 0;
static size_t  q_cap  = 0;

/* ensure cache holds at least n terms (n≥1) */
static void ensure_cache(size_t n)
{
    if (cache_len >= n) return;

    /* first call – initialise */
    if (cache == NULL) {
        cache_cap = 16;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        cache[0] = (seq_t)1;        /* a(1) */
        cache_len = 1;

        q_cap  = 16;
        queue  = (seq_t *)malloc(q_cap * sizeof(seq_t));
        q_head = q_tail = 0;
        queue[q_tail++] = (seq_t)2;   /* child of the root */
    }

    /* generate terms until we have enough */
    while (cache_len < n) {
        /* take next node from the queue */
        if (q_head >= q_tail) return; /* safety */

        seq_t node = queue[q_head++];

        /* grow cache if needed */
        if (cache_len >= cache_cap) {
            cache_cap *= 2;
            cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
        }
        cache[cache_len++] = node;

        /* children of node (node is ≥2) */
        seq_t sq3 = floor_sqrt((seq_t)3 * node * node);           /* floor(√3·node)  */
        seq_t child0 = sq3;
        seq_t child1 = ((seq_t)3 * node + child0) / 2;            /* floor(s·node)   */

        /* grow queue if needed */
        if (q_tail + 2 > q_cap) {
            q_cap *= 2;
            queue = (seq_t *)realloc(queue, q_cap * sizeof(seq_t));
        }
        queue[q_tail++] = child0;
        queue[q_tail++] = child1;
    }
}

seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;                 /* undefined for n=0 */

    ensure_cache((size_t)n);
    return cache[n - 1];
}
